// Which check runs: "new" (every 10 min: new orders) or "late" (daily 8:45: paid orders not shipped). Reuses the token if still valid.
const mode = $input.first().json.mode || 'new';
const t = $getWorkflowStaticData('global').shopToken;
const since = new Date(Date.now() - (mode === 'late' ? 30 : 3) * 864e5).toISOString().slice(0, 10);
const q = mode === 'late' ? `created_at:>=${since} financial_status:paid fulfillment_status:unshipped status:open` : `created_at:>=${since}`;
return [{ json: { mode, need_token: !(t && t.until > Date.now()), gql: { query:
  'query($q: String!) { orders(first: 50, sortKey: CREATED_AT, reverse: true, query: $q) { nodes { id name createdAt cancelledAt displayFinancialStatus displayFulfillmentStatus currencyCode ' +
  'totalPriceSet { shopMoney { amount } } totalTaxSet { shopMoney { amount } } shippingAddress { city provinceCode } ' +
  'lineItems(first: 20) { nodes { title quantity sku originalUnitPriceSet { shopMoney { amount } } } } } } }', variables: { q } } } }];

// Shopify access token (Dev Dashboard app, client credentials): valid about 24 h, kept in workflow data.
const store = $getWorkflowStaticData('global');
const r = $input.first().json || {};
if (r.access_token) store.shopToken = { value: r.access_token, until: Date.now() + (Number(r.expires_in) || 86399) * 1000 - 600000 };
const t = store.shopToken;
return [{ json: { ...$('Which check?').first().json, shop_token: t && t.until > Date.now() ? t.value : null,
                  token_error: r.access_token ? null : (r.error ? String(r.error.message || r.error_description || r.error).slice(0, 200) : null) } }];

// Shopify GraphQL orders -> the simple order format used by "Format order" and "Late orders".
// New orders = not seen before (remembered in workflow data). First run: remembers existing orders silently.
const r = $input.first().json || {};
const nodes = (((r.data || {}).orders || {}).nodes) || [];
const amt = m => Number((m && m.shopMoney && m.shopMoney.amount) || 0);
const orders = nodes.map(o => ({
  id: o.id, name: o.name, created_at: o.createdAt, cancelled_at: o.cancelledAt,
  financial_status: String(o.displayFinancialStatus || '').toLowerCase(),
  fulfillment_status: /FULFILLED/.test(o.displayFulfillmentStatus || '') && o.displayFulfillmentStatus !== 'UNFULFILLED' ? (o.displayFulfillmentStatus === 'PARTIALLY_FULFILLED' ? 'partial' : 'fulfilled') : null,
  currency: o.currencyCode || 'CAD', total_price: amt(o.totalPriceSet).toFixed(2), total_tax: amt(o.totalTaxSet).toFixed(2),
  shipping_address: o.shippingAddress ? { city: o.shippingAddress.city, province_code: o.shippingAddress.provinceCode } : null,
  line_items: ((o.lineItems || {}).nodes || []).map(li => ({ title: li.title, quantity: li.quantity, sku: li.sku || '', price: amt(li.originalUnitPriceSet) })),
}));
const mode = $('Which check?').first().json.mode;
if (mode === 'late') return orders.length ? orders.map(o => ({ json: o })) : [{ json: {} }];
const store = $getWorkflowStaticData('global');
const first = !store.seenOrders;
store.seenOrders = store.seenOrders || [];
const fresh = orders.filter(o => !store.seenOrders.includes(o.id));
store.seenOrders = [...fresh.map(o => o.id), ...store.seenOrders].slice(0, 300);
if (first || !fresh.length) return [];
return fresh.reverse().map(o => ({ json: o }));

// New Rangéo order (Shopify webhook orders/create) -> Telegram alert + memory row.
// COSTS: supplier cost + shipping in USD per CJ SKU (from CJ). Add a line for each new product.
const COSTS = { 'CJQCNBQC00122-Black': 12.90 };
const USD_TO_CAD = 1.40, FEE_PCT = 0.029, FEE_FIXED = 0.30;
function format(o) {
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const items = (o.line_items || []).map(li => ({ title: li.title || li.name || '?', qty: Number(li.quantity) || 1, sku: li.sku || '', price: Number(li.price) || 0 }));
const total = Number(o.total_price ?? o.current_total_price ?? 0);
const tax = Number(o.total_tax ?? 0);
let cost = 0, unknown = [];
for (const it of items) {
  const key = Object.keys(COSTS).find(k => it.sku && (it.sku === k || it.sku.includes(k) || k.includes(it.sku)));
  if (key) cost += COSTS[key] * USD_TO_CAD * it.qty; else unknown.push(it.title);
}
const fees = total * FEE_PCT + FEE_FIXED;
const profit = unknown.length ? null : +(total - tax - cost - fees).toFixed(2);
const city = [o.shipping_address?.city, o.shipping_address?.province_code].filter(Boolean).join(', ');
const local = new Date(o.created_at || Date.now()).toLocaleString('en-CA', { timeZone: 'America/Toronto', dateStyle: 'medium', timeStyle: 'short' });
const text = [
  '🛒 <b>New Rangéo order ' + esc(o.name || ('#' + (o.order_number || ''))) + '</b>',
  ...items.map(it => '• ' + it.qty + ' × ' + esc(it.title)),
  'Total: ' + total.toFixed(2) + ' ' + esc(o.currency || 'CAD') + (tax ? ' (tax ' + tax.toFixed(2) + ')' : ''),
  profit !== null ? 'Est. profit: ~' + profit + ' CAD (before ads)' : 'Est. profit: unknown (add the cost of ' + esc(unknown.join(', ')) + ' to COSTS)',
  city ? 'Ship to: ' + esc(city) : '',
  'Payment: ' + esc(o.financial_status || '?') + ' · ' + esc(local),
  'CJ will pay and ship it automatically at the next time point (9:00 / 17:00).',
].filter(Boolean).join('\n');
const summary = `New Rangéo order ${o.name || ''} (${local}): ${items.map(i => i.qty + 'x ' + i.title).join(', ')}; total ${total.toFixed(2)} ${o.currency || 'CAD'}` + (profit !== null ? `; est. profit ~${profit} CAD` : '');
return { text, kind: 'order', summary: summary.slice(0, 1500) };
}
// One alert per new order (Shop v2 can find several at once).
return $input.all().map(i => ({ json: format(i.json || {}) }));

// Daily check: paid Rangéo orders still not shipped after 4 days -> one Telegram alert (silent otherwise).
const DAYS = 4;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const orders = $input.all().map(i => i.json || {}).filter(o => o.id && o.created_at && !o.cancelled_at);
const late = orders.filter(o => (Date.now() - new Date(o.created_at)) / 86400e3 > DAYS && (o.fulfillment_status === null || o.fulfillment_status === undefined || o.fulfillment_status === 'partial'));
const text = '⚠️ <b>Rangéo: ' + late.length + ' order(s) not shipped after ' + DAYS + ' days</b>\n' +
  late.slice(0, 10).map(o => '• ' + esc(o.name) + ' from ' + new Date(o.created_at).toLocaleDateString('en-CA', { timeZone: 'America/Toronto' }) + ', ' + esc(o.total_price) + ' ' + esc(o.currency)).join('\n') +
  '\nCheck CJ → Orders: unpaid, out of stock, or address problem? Customers may ask for refunds if it waits too long.';
return [{ json: { send: late.length > 0, text, kind: 'error', summary: `Rangéo: ${late.length} order(s) not shipped after ${DAYS} days: ${late.map(o => o.name).join(', ')}` } }];
